    "abilities": "da cocatriz fica lenta (Fort CD 19 evita). Se já estiver lenta, fica petrificada permanentemente. Efeitos que removem paralisia revertem a petrificação. Voo de Galinha A cocatriz só consegue percorrer curtas distâncias voando; ela sempre termina seu movimento sobre o chão ou outra superfície firme. Tesouro 1d4-1 ovos de cocatriz (cada ovo permite preparar uma refeição coc-au-triz ). Parceiro A cocatriz é um parceiro especial (adepto) que fornece os benefícios a seguir. Iniciante:  suas habilidades mágicas que causam condições de movimento têm o custo reduzido em –1 PM. Veterano: a CD para resistir a essas habilidades aumenta em +2. Mestre: a redução de custo se torna cumulativa com outras reduções. CocatrizCocatriz",
